cat pyproject.toml | head -45; cat more_itertools/__init__.py; python3 - <<'EOF'
import ast, more_itertools.more as m, more_itertools.recipes as r
for mod,f in ((m,'more'),(r,'recipes')):
    src=ast.parse(open(f'more_itertools/{f}.py').read())
    defs={n.name for n in src.body if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and not n.name.startswith('_')}
    print(f,'not in __all__:',defs-set(mod.__all__))
    stub=ast.parse(open(f'more_itertools/{f}.pyi').read())
    sd={n.name for n in stub.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))} | {t.id for n in stub.body if isinstance(n,ast.Assign) for t in n.targets if isinstance(t,ast.Name)}
    print(f,'missing in stub:',set(mod.__all__)-sd)
EOF

